// Site image-model id -> OpenAI upstream model id, for the rows generated by OpenAI directly
// (/v1/images/generations and /v1/images/edits).
//
// GPT Image 2.5 and 2.6 (Flare + Sunburst) are NOT here: they are served through WaveSpeed
// (see resolveWaveSpeedImageModelRoute in lib/wavespeed-image-routing.ts).
//
// Lives in lib/ because a Next.js route file may only export route handlers, and the
// routing test needs to read this map.
export const OPENAI_IMAGE_MODEL_MAP: Record<string, string> = {
  // Released 2026-09-08. Both variants sit on /v1/images/generations and
  // /v1/images/edits, exactly like gpt-image-2, so generateOpenAIImage needs
  // no change — only the id mapping.
  "gpt-image-2-text-to-image": "gpt-image-2",
  "gpt-image-2-image-to-image": "gpt-image-2",
  "gpt-image/1.5-text-to-image": "gpt-image-1.5",
  "gpt-image/1.5-image-to-image": "gpt-image-1.5",
};
